import sys, pathlib; sys.path.insert(0, str(pathlib.Path(__file__).parent))
from corlib import *
E = []
S = lambda ch, a, b=None: C("snell", ch, a, b)
B = lambda ch, a, b=None: C("berkowitz", ch, a, b)
MCA_I = ["artery-mca", "artery-mca-inferior-division"]; MCA_S = ["artery-mca", "artery-mca-superior-division"]; PCA = ["artery-pca"]; ACA = ["artery-aca"]

E.append(cortex("gyrus-supramarginal-anterior", "Supramarginal gyrus, anterior division", "parietal",
 "The anterior supramarginal gyrus caps the upturned end of the lateral sulcus behind the postcentral gyrus, the front part of the inferior parietal lobule (Brodmann area 40). It is where touch, proprioception and hearing meet the motor plans of the frontal lobe: in the dominant hemisphere it stores the spatiotemporal programs of learned skilled movements and the phonological loop used to repeat and to hold speech in mind, and in the right hemisphere it directs attention to the contralateral side of space. It is a middle cerebral artery territory at the junction of the superior and inferior divisions, and its lesions produce ideomotor apraxia, conduction aphasia and neglect.",
 "Anterior part of the inferior parietal lobule, arching over the posterior end of the lateral sulcus, behind the postcentral sulcus, in front of the posterior division and the angular gyrus, above the planum temporale.",
 "The anterior supramarginal cortex integrates somatosensory and auditory information with body schema and stores, in the left hemisphere, the representations of gestures and tool use that the premotor cortex executes; its loss produces ideomotor apraxia in which the patient knows what to do but cannot perform it to command, on both sides of the body because the right premotor cortex depends on it through the corpus callosum. It also holds the phonological store of verbal working memory and takes part in repetition through the arcuate fasciculus, and on the right it is part of the ventral attention network that reorients attention to unexpected stimuli, whose loss produces neglect and extinction.",
 MCA_S + MCA_I,
 [mview("axial", "gyrus-supramarginal-anterior-l", "anterior supramarginal gyrus capping the Sylvian fissure"), mview("coronal", "gyrus-supramarginal-anterior-r", "inferior parietal lobule above the posterior Sylvian fissure")],
 "The gyrus that wraps around the posterior end of the Sylvian fissure on axial images above the posterior insula, behind the postcentral gyrus and in front of the angular gyrus.",
 [pathol("MCA infarct with apraxia or conduction aphasia", "MRI", "Restricted diffusion of the left inferior parietal cortex and the underlying arcuate fibers; the patient cannot pantomime tool use and cannot repeat.", sequence="DWI"),
  pathol("Right parietal infarct with neglect", "MRI", "Right inferior parietal cortical infarct with left neglect, extinction and anosognosia.", sequence="DWI"),
  pathol("Corticobasal syndrome", "MRI", "Asymmetric parietal atrophy including the supramarginal gyrus in a patient with limb apraxia, dystonia and alien limb.", sequence="T1")],
 [("Ideomotor apraxia of both hands (left)", "bilateral", "Loss of stored movement representations in the dominant inferior parietal lobule"), ("Conduction aphasia: impaired repetition with phonemic errors (left)", "n/a", "Damage to the phonological store and the arcuate fasciculus beneath it"), ("Contralateral neglect and extinction (right)", "contralateral", "Loss of the ventral attention network node of the right inferior parietal lobule")],
 ["Pantomime tool use to command and imitation of meaningless gestures with either hand", "Repetition of multisyllabic words and sentences", "Double simultaneous stimulation and line bisection for neglect"],
 ["Apraxia from a left parietal lesion affects the left hand too: the right hemisphere gets its movement formulas through the callosum", "Conduction aphasia is a supramarginal-arcuate lesion: fluent, comprehending, unable to repeat", "Neglect is a right inferior parietal sign; test extinction, not just fields"],
 [S(8, 288, 291), S(7, 258), B(7, 53, 60)], synonyms=["anterior inferior parietal lobule", "area 40"], territories=["territory-mca-parietal"], pathways=["pathway-dcml"], syndromes=["syn-aphasia-conduction-global", "syn-hemineglect", "syn-mca-inferior-division"],
 afferents=[("Postcentral gyrus and secondary somatosensory cortex", "short association fibers"), ("Planum temporale and posterior superior temporal gyrus", "arcuate fasciculus"), ("Pulvinar and lateral posterior thalamus", "posterior thalamic radiation")],
 efferents=[("Premotor cortex and inferior frontal gyrus", "superior longitudinal fasciculus III / arcuate fasciculus"), ("Contralateral supramarginal gyrus", "corpus callosum"), ("Superior colliculus and pulvinar (attention)", "corticofugal fibers")],
 pitfalls=["Apraxia is missed unless tested: ask the patient to show how they would use a comb, a key and scissors without the object"], tags=["inferior parietal lobule", "praxis", "phonological loop"]))

E.append(cortex("gyrus-supramarginal-posterior", "Supramarginal gyrus, posterior division", "parietal",
 "The posterior supramarginal gyrus lies between the anterior division and the angular gyrus in the inferior parietal lobule, above the posterior end of the superior temporal sulcus. It is multimodal association cortex that integrates the location of the body and of objects around it and, in the dominant hemisphere, links the sounds of words to their spelling and to the movements of writing; in the right hemisphere it contributes to spatial attention and to the perception of one's own body. It is supplied by parietal branches of the middle cerebral artery, is a watershed with the posterior cerebral artery below, and its lesions add agraphia, spatial disorientation and elements of the Gerstmann syndrome to those of the anterior division.",
 "Posterior part of the inferior parietal lobule between the anterior supramarginal gyrus in front and the angular gyrus behind, above the superior temporal sulcus and below the intraparietal sulcus.",
 "This cortex represents the position of the limbs and of objects in body-centered coordinates for reaching and grasping, and links auditory word forms with their written form, supporting spelling and writing in the left hemisphere; it is part of the dorsal attention and the sensorimotor integration networks that keep the body schema updated. In the right hemisphere it participates in the sense of ownership of the limbs and in the perception of the contralateral hemispace, and its damage contributes to neglect, asomatognosia and anosognosia. It also receives vestibular input through the parieto-insular vestibular cortex, so lesions can produce a sensation of tilt or of leaving the body.",
 MCA_I + PCA,
 [mview("axial", "gyrus-supramarginal-posterior-l", "posterior supramarginal gyrus in front of the angular gyrus"), mview("coronal", "gyrus-supramarginal-posterior-r", "inferior parietal lobule above the superior temporal sulcus")],
 "The middle part of the inferior parietal lobule on axial images above the atrium, between the upturned Sylvian fissure and the upturned superior temporal sulcus that marks the angular gyrus.",
 [pathol("Posterior MCA branch infarct", "MRI", "Cortical restricted diffusion of the posterior inferior parietal lobule with agraphia and finger agnosia (left) or spatial neglect (right).", sequence="DWI"),
  pathol("Posterior cortical atrophy", "MRI", "Bilateral inferior parietal and occipital atrophy with agraphia, acalculia and visuospatial disorientation.", sequence="T1"),
  pathol("Parietal seizures", "EEG", "Somatosensory auras of tingling, a feeling of the limb being absent or displaced, or vertigo, with a parietal EEG focus.", sequence="n/a")],
 [("Agraphia and spelling errors (left)", "n/a", "Disconnection of phonological and orthographic word forms in the dominant inferior parietal lobule"), ("Contralateral neglect and asomatognosia (right)", "contralateral", "Loss of the right inferior parietal representation of contralateral space and body"), ("Disturbed body schema and vestibular illusions", "contralateral", "Involvement of the parietal vestibular and body-schema cortex")],
 ["Writing to dictation and spelling aloud", "Line bisection, figure copying and drawing a clock", "Ask about out-of-body sensations, tilt or the feeling that a limb is not theirs"],
 ["Agraphia without aphasia is inferior parietal; test writing separately from speech", "Asomatognosia (denial of one's own arm) is a right posterior parietal sign", "Vertigo with a normal vestibular examination can be a parietal seizure"],
 [S(8, 288, 291), S(7, 258), B(7, 58, 60), B(22, 236, 238)], synonyms=["posterior inferior parietal lobule"], territories=["territory-mca-parietal"], pathways=["pathway-dcml", "pathway-vestibular-vor"], syndromes=["syn-gerstmann", "syn-hemineglect"],
 afferents=[("Superior parietal lobule and intraparietal cortex", "short association fibers"), ("Posterior superior temporal gyrus", "middle longitudinal fasciculus"), ("Vestibular thalamic relay", "thalamocortical fibers")],
 efferents=[("Premotor and prefrontal cortex", "superior longitudinal fasciculus II"), ("Angular gyrus", "short association fibers"), ("Contralateral inferior parietal lobule", "corpus callosum")],
 pitfalls=["Anosognosia means the patient will not report the deficit; rely on examination and the family"], tags=["inferior parietal lobule", "body schema", "writing"]))

E.append(cortex("precuneus", "Precuneus", "parietal",
 "The precuneus is the medial surface of the parietal lobe, a quadrilateral area behind the paracentral lobule and in front of the parieto-occipital sulcus, above the posterior cingulate gyrus and the splenium. It is a hub of the default mode network with the posterior cingulate, active in self-referential thought, episodic memory retrieval, mental imagery and the sense of first-person perspective, and it is one of the first regions to lose metabolism and to accumulate amyloid in Alzheimer disease. It is supplied by the anterior cerebral artery through the pericallosal and parieto-occipital branches, and it is compressed by parasagittal and falcine tumors; bilateral disconnection contributes to the loss of consciousness in generalized seizures and anesthesia.",
 "Medial parietal cortex between the marginal branch of the cingulate sulcus in front, the parieto-occipital sulcus behind and the subparietal sulcus below, continuous over the superior margin with the superior parietal lobule.",
 "The precuneus retrieves autobiographical memories and imagines scenes from a first-person point of view, integrating egocentric space with the self; together with the posterior cingulate it is the most metabolically active region of the resting brain and deactivates during attention-demanding tasks. Its dorsal part guides visually directed reaching and shifts of spatial attention with the superior parietal lobule, and its ventral part connects with the hippocampus through the cingulum and the retrosplenial cortex. Loss of its function produces impaired navigation, disturbed self-awareness and, when bilateral with the posterior cingulate, the amnesia and disorientation of early Alzheimer disease.",
 ACA + PCA,
 [mview("sagittal", "precuneus-l", "precuneus on the medial parietal surface in front of the parieto-occipital sulcus"), mview("coronal", "precuneus-r", "medial parietal cortex above the splenium")],
 "Medial parietal cortex on midline sagittal images between the marginal ramus of the cingulate sulcus and the deep parieto-occipital sulcus; the subparietal sulcus separates it from the posterior cingulate below.",
 [pathol("Alzheimer disease", "PET", "Hypometabolism of the precuneus and posterior cingulate on FDG-PET and early amyloid deposition, preceding lateral parietal and temporal changes.", sequence="n/a"),
  pathol("Parasagittal meningioma", "MRI", "Dural-based enhancing mass indenting the medial parietal cortex with sensory seizures or contralateral leg symptoms.", sequence="T1+Gd"),
  pathol("Posterior reversible encephalopathy syndrome", "MRI", "Symmetric vasogenic edema of the parieto-occipital cortex including the precuneus, with headache, seizures and visual symptoms.", sequence="FLAIR", timing="Resolves within days to weeks with control of blood pressure")],
 [("Impaired episodic memory retrieval and mental imagery", "bilateral", "Loss of the precuneus-posterior cingulate retrieval hub"), ("Topographical disorientation", "bilateral", "Disconnection of the precuneus and retrosplenial cortex from the hippocampus"), ("Contralateral leg sensory symptoms and seizures", "contralateral", "Involvement of the adjacent paracentral lobule by a medial parietal lesion")],
 ["Route finding and describing familiar routes", "Autobiographical memory for specific events", "Sensation and strength of the contralateral leg"],
 ["The precuneus and posterior cingulate go dark on FDG-PET years before Alzheimer dementia is diagnosed", "Medial parietal lesions disturb the sense of self and of place more than any sensory modality", "A parasagittal mass can be silent until the leg is affected or a sensory seizure occurs"],
 [S(7, 259), S(8, 288, 291), B(22, 233, 238), B(7, 58, 60)], synonyms=["medial parietal cortex", "area 7 (medial)"], territories=["territory-aca", "territory-pca-occipital"], pathways=["pathway-papez-limbic"], syndromes=["syn-aca-infarct"],
 afferents=[("Posterior cingulate and retrosplenial cortex", "cingulum"), ("Superior parietal lobule", "short association fibers"), ("Pulvinar and lateral posterior thalamus", "posterior thalamic radiation")],
 efferents=[("Hippocampus and parahippocampal cortex", "cingulum"), ("Medial prefrontal cortex (default mode)", "cingulum"), ("Frontal eye field and premotor cortex", "superior longitudinal fasciculus I")],
 pitfalls=["Precuneal atrophy is hard to judge visually; rely on FDG-PET or quantitative volumetry when early Alzheimer disease is the question"], tags=["default mode", "medial parietal", "Alzheimer"]))

E.append(cortex("cortex-parietal-operculum", "Parietal operculum cortex", "parietal",
 "The parietal operculum is the part of the parietal lobe that folds under the posterior lateral sulcus above the posterior insula and the planum temporale, behind the central operculum. It contains the secondary somatosensory cortex (SII) and the parieto-insular vestibular cortex, so it is the cortex of tactile object recognition, of the affective dimension of pain, and of the conscious sense of head motion and verticality. It is a middle cerebral artery territory, and its lesions produce impaired stereognosis and tactile learning, altered pain perception, and vertigo or tilt illusions; seizures here give bilateral tingling, pain or a sense of motion.",
 "Buried parietal cortex forming the roof of the posterior Sylvian fissure between the central operculum in front and the supramarginal gyrus behind, above the planum temporale and the posterior insula.",
 "SII receives touch and proprioception from both sides of the body through the primary somatosensory cortex and the thalamus, with the two hands represented together, and it integrates them for recognizing objects by touch, learning tactile skills and attending to a stimulus; it also receives nociceptive input and, with the insula and cingulate, gives pain its unpleasant and motivational quality. The adjacent parieto-insular vestibular cortex combines vestibular, visual and neck proprioceptive signals to perceive self-motion and the vertical. Both sides of the body are represented, so a unilateral lesion produces subtler and bilateral tactile deficits than a postcentral lesion.",
 MCA_I,
 [mview("coronal", "cortex-parietal-operculum-l", "parietal operculum above the posterior insula"), mview("axial", "cortex-parietal-operculum-r", "roof of the posterior Sylvian fissure")],
 "The upper bank of the posterior Sylvian fissure on coronal images through the posterior insula, between the postcentral gyrus above and the planum temporale below.",
 [pathol("Opercular MCA branch infarct", "MRI", "Small cortical restricted diffusion at the parietal operculum with impaired stereognosis, tactile extinction and sometimes vertigo.", sequence="DWI"),
  pathol("Parietal opercular seizures", "EEG", "Bilateral or contralateral tingling, painful auras or a sensation of rotation; scalp EEG shows a centro-parietal focus.", sequence="n/a"),
  pathol("Central post-stroke pain", "MRI", "Lesion involving the parietal operculum, insula or thalamus with delayed burning pain and allodynia in the contralateral limbs.", sequence="FLAIR")],
 [("Astereognosis and impaired tactile learning", "contralateral", "Loss of the SII integration of touch and proprioception"), ("Altered pain perception or central pain", "contralateral", "Damage to the opercular-insular nociceptive cortex"), ("Vertigo, tilt and loss of the subjective vertical", "contralateral", "Involvement of the parieto-insular vestibular cortex")],
 ["Stereognosis: identify coins and keys placed in the hand with eyes closed", "Bilateral simultaneous tactile stimulation for extinction", "Subjective visual vertical (ask the patient to set a line upright) and a history of tilt illusions"],
 ["SII is bilateral: a unilateral lesion impairs tactile recognition subtly, not with anesthesia", "Painful seizures are rare and almost always parietal opercular or insular", "The vestibular cortex sits here: cortical vertigo exists and is not a brainstem sign"],
 [S(8, 286, 288), S(7, 258), B(7, 53, 58), B(12, 108, 112)], synonyms=["secondary somatosensory cortex (SII)", "parieto-insular vestibular cortex"], territories=["territory-mca-parietal", "territory-mca-insular"], pathways=["pathway-dcml", "pathway-lateral-spinothalamic", "pathway-vestibular-vor"], syndromes=["syn-mca-inferior-division", "syn-central-vs-peripheral-vertigo"],
 afferents=[("Postcentral gyrus (SI), both sides", "short association fibers and corpus callosum"), ("Ventral posterior thalamus and posterior nuclear group", "thalamocortical fibers"), ("Vestibular thalamic relay", "thalamocortical fibers")],
 efferents=[("Insula and anterior cingulate", "short association fibers"), ("Premotor cortex", "superior longitudinal fasciculus III"), ("Posterior parietal cortex", "short association fibers")],
 pitfalls=["Astereognosis with intact primary sensation is cortical; do not attribute it to a neuropathy"], tags=["SII", "vestibular cortex", "pain"]))

E.append(cortex("cuneus", "Cuneus", "occipital",
 "The cuneus is the wedge of medial occipital cortex above the calcarine sulcus and below the parieto-occipital sulcus, the upper bank of the primary visual cortex and its surrounding extrastriate areas (V1 above the sulcus, V2 and V3 on the cuneal surface). It represents the contralateral inferior visual field, so a cuneal lesion produces a contralateral inferior quadrantanopia. It is supplied by the calcarine and parieto-occipital branches of the posterior cerebral artery with a middle cerebral artery contribution at the occipital pole, which explains macular sparing after PCA occlusion, and it is the cortex of the visual auras of occipital epilepsy and migraine.",
 "Medial occipital surface between the calcarine sulcus below and the parieto-occipital sulcus above, extending from the occipital pole forward to the junction of the two sulci behind the splenium.",
 "The cuneal part of the primary visual cortex receives the upper bank of the optic radiation carrying the contralateral lower visual field, with the periphery represented anteriorly and the macula toward the pole, and passes the retinotopic map to the surrounding V2 and V3 on the cuneus and to dorsal-stream areas of the parietal lobe for the localization of objects and the guidance of action. Damage produces a congruous inferior quadrantic field defect, and irritation produces elementary hallucinations of flashes and colored shapes in the lower contralateral field. The cuneus also participates in visual attention and reading, and in the visual imagery that accompanies memory retrieval.",
 PCA + MCA_I,
 [mview("sagittal", "cuneus-l", "cuneus above the calcarine sulcus"), mview("coronal", "cuneus-r", "medial occipital cortex between the calcarine and parieto-occipital sulci")],
 "Triangular medial occipital cortex on sagittal images between the deep calcarine and parieto-occipital sulci; the stria of Gennari is visible as a thin dark line in the calcarine cortex on high-resolution T1 images.",
 [pathol("PCA infarct (upper calcarine bank)", "MRI", "Restricted diffusion of the cuneus with a contralateral inferior quadrantanopia; macular sparing when the pole is supplied by the MCA.", sequence="DWI"),
  pathol("Occipital epilepsy", "EEG", "Brief elementary visual hallucinations of colored circles in the contralateral lower field followed by eye deviation; occipital spikes that increase with eye closure.", sequence="n/a"),
  pathol("Posterior reversible encephalopathy syndrome", "MRI", "Bilateral parieto-occipital vasogenic edema including the cuneus with cortical blindness or visual disturbance.", sequence="FLAIR")],
 [("Contralateral inferior quadrantanopia", "contralateral", "Loss of the upper calcarine bank representing the lower visual field"), ("Elementary visual hallucinations in the lower contralateral field", "contralateral", "Ictal activation of the cuneal visual cortex"), ("Impaired visually guided reaching and attention to the lower field", "contralateral", "Loss of cuneal input to the dorsal visual stream")],
 ["Confrontation fields by quadrant with finger counting or a red target", "Ask about flashes or colored shapes and their duration and side", "Reading and scanning of a page for lower-field neglect of text"],
 ["Above the calcarine sulcus means below the horizontal meridian: cuneal lesions cut the lower field", "Occipital seizure auras last seconds and are colored; migraine auras last minutes and are black and white zigzags", "Macular sparing is the fingerprint of a PCA infarct with an intact MCA collateral at the occipital pole"],
 [S(8, 288, 289), S(7, 259, 260), S(11, 333, 336), B(6, 47, 52)], synonyms=["upper calcarine bank", "medial occipital cortex (superior)"], territories=["territory-pca-occipital"], pathways=["pathway-visual"], syndromes=["syn-homonymous-hemianopia", "syn-pca-infarct", "syn-anton"],
 afferents=[("Lateral geniculate nucleus (lower field fibers)", "optic radiation, upper bank"), ("Pulvinar", "thalamocortical fibers"), ("Contralateral visual cortex", "splenium of the corpus callosum")],
 efferents=[("Superior parietal and lateral occipital cortex (dorsal stream)", "short association fibers"), ("Superior colliculus and pretectum", "corticotectal fibers"), ("Lateral geniculate nucleus (feedback)", "corticogeniculate fibers")],
 pitfalls=["Quadrantic defects are missed by testing hemifields only; count fingers in each of the four quadrants"], tags=["V1", "visual field", "lower quadrant"]))

E.append(cortex("cortex-lateral-occipital-superior", "Lateral occipital cortex, superior division", "occipital",
 "The superior lateral occipital cortex is the upper part of the convex outer surface of the occipital lobe, above the lateral occipital sulcus and behind the parieto-occipital junction, corresponding to dorsal extrastriate visual areas (V3A, V6 and the lateral occipital complex) that lead into the parietal dorsal stream. It represents where objects are and how they move relative to the observer and guides eye and hand movements toward them, and it is a watershed between the middle and posterior cerebral arteries. Lesions produce optic ataxia, defective motion perception and the simultanagnosia of Balint syndrome when bilateral, and the region is damaged early in posterior cortical atrophy.",
 "Upper lateral surface of the occipital lobe from the parieto-occipital sulcus and the superior parietal lobule down to the lateral occipital sulcus, and from the occipital pole forward to the angular gyrus.",
 "Dorsal extrastriate cortex here computes the position of objects in eye- and head-centered coordinates, their motion and the optic flow produced by self-movement, and passes this to the intraparietal cortex for reaching, grasping and shifting attention; it also contains part of the shape-selective lateral occipital complex. It is retinotopic with the contralateral lower field, and it contributes to visually guided saccades and to the perception of depth and of three-dimensional structure from motion. Bilateral damage leaves the patient able to see single objects but unable to perceive the scene as a whole or to reach for what is seen.",
 PCA + MCA_I,
 [mview("axial", "cortex-lateral-occipital-superior-l", "superior lateral occipital cortex behind the angular gyrus"), mview("sagittal", "cortex-lateral-occipital-superior-r", "dorsolateral occipital convexity")],
 "Convex lateral occipital cortex above the lateral occipital sulcus on axial images above the atria, behind the angular gyrus and lateral to the parieto-occipital sulcus.",
 [pathol("Bilateral parieto-occipital watershed infarcts", "MRI", "Symmetric border-zone restricted diffusion in the superior lateral occipital and parietal cortex after hypotension, producing Balint syndrome.", sequence="DWI"),
  pathol("Posterior cortical atrophy", "MRI", "Bilateral dorsal occipito-parietal atrophy with simultanagnosia, optic ataxia and ocular apraxia; hippocampi relatively spared.", sequence="T1"),
  pathol("Posterior reversible encephalopathy syndrome", "MRI", "Cortical and subcortical vasogenic edema of the occipito-parietal convexity with visual disturbance and seizures.", sequence="FLAIR")],
 [("Optic ataxia: misreaching for seen objects", "contralateral", "Loss of the dorsal-stream transformation from visual location to hand movement"), ("Simultanagnosia when bilateral", "bilateral", "Loss of the ability to integrate multiple objects into a scene"), ("Impaired motion perception and visually guided saccades", "contralateral", "Damage to dorsal motion and attention areas")],
 ["Reaching for a target in the peripheral field while fixating centrally", "Describe a complex picture: does the patient report only one item at a time?", "Visual fields and pursuit and saccade accuracy"],
 ["Balint syndrome is bilateral dorsal occipito-parietal disease: the patient sees but cannot find, reach or take in a scene", "The occipito-parietal border zone is the cortex most vulnerable to a drop in perfusion in both hemispheres", "Posterior cortical atrophy is Alzheimer disease starting in the dorsal visual stream; memory comes later"],
 [S(8, 288, 291), S(7, 258, 260), B(6, 47, 52), B(7, 58, 60), B(22, 236, 238)], synonyms=["dorsal extrastriate cortex", "areas 18/19 (superior lateral)"], territories=["territory-pca-occipital", "territory-mca-occipital"], pathways=["pathway-visual"], syndromes=["syn-balint", "syn-watershed-infarct"],
 afferents=[("Primary visual cortex and cuneus", "short association fibers"), ("Pulvinar", "thalamocortical fibers"), ("Contralateral lateral occipital cortex", "splenium")],
 efferents=[("Superior parietal lobule and intraparietal sulcus", "short association fibers"), ("Frontal eye field", "superior longitudinal fasciculus"), ("Middle temporal motion area", "short association fibers")],
 pitfalls=["Simultanagnosia can pass as poor vision on acuity testing; the patient reads letters but not the scene"], tags=["dorsal stream", "watershed", "Balint"]))

E.append(cortex("cortex-lateral-occipital-inferior", "Lateral occipital cortex, inferior division", "occipital",
 "The inferior lateral occipital cortex is the lower part of the outer surface of the occipital lobe, below the lateral occipital sulcus and above the preoccipital notch, continuous in front with the temporo-occipital cortex. It contains the shape- and object-selective cortex of the lateral occipital complex and part of the extrastriate body area, the beginning of the ventral visual stream that identifies what is seen. It is supplied by the posterior cerebral artery with a middle cerebral artery contribution laterally, and its lesions cause apperceptive agnosia and contralateral upper quadrant defects; the region is a frequent site of visual auras and of the hallucinations of Charles Bonnet syndrome.",
 "Lower lateral occipital surface between the lateral occipital sulcus above and the inferior margin of the hemisphere at the preoccipital notch, behind the inferior temporal gyrus and lateral to the occipital fusiform gyrus.",
 "Neurons of the lateral occipital complex respond to the shape of objects regardless of the cues that define them, whether luminance edges, texture or motion, and represent bodies and body parts in an adjacent patch; this shape information feeds the fusiform and inferior temporal recognition areas. The region is retinotopic for the contralateral upper field and it contributes to the perception of depth and of figure from ground. Damage produces apperceptive agnosia with inability to copy or match shapes despite intact acuity, and release phenomena produce formed hallucinations of objects and figures when the input is lost.",
 PCA + MCA_I,
 [mview("axial", "cortex-lateral-occipital-inferior-l", "inferior lateral occipital cortex above the preoccipital notch"), mview("coronal", "cortex-lateral-occipital-inferior-r", "lower lateral occipital convexity")],
 "Lateral occipital cortex below the lateral occipital sulcus on axial images through the level of the atria and below, behind the temporo-occipital junction.",
 [pathol("PCA branch infarct", "MRI", "Restricted diffusion of the inferior lateral occipital cortex with a contralateral upper quadrantanopia and impaired shape perception.", sequence="DWI"),
  pathol("Charles Bonnet syndrome", "MRI", "Formed visual hallucinations of people or patterns in a patient with visual loss from any cause; imaging excludes a structural occipital lesion.", sequence="FLAIR"),
  pathol("Occipital cortical dysplasia or tumor", "MRI", "Focal FLAIR-bright cortex at the lateral occipital surface in a patient with visual seizures.", sequence="FLAIR")],
 [("Apperceptive visual agnosia", "contralateral", "Loss of shape integration in the lateral occipital complex"), ("Contralateral superior quadrantanopia", "contralateral", "Involvement of the ventral extrastriate cortex or the lower optic radiation"), ("Formed visual hallucinations", "n/a", "Release or ictal activation of object-selective visual cortex")],
 ["Copy and match simple shapes and letters", "Quadrantic visual fields", "Ask about hallucinations of people, animals or patterns and whether the patient knows they are unreal"],
 ["Charles Bonnet hallucinations are unreal and known to be unreal by the patient; they are a sign of visual loss, not psychosis", "An apperceptive agnosic cannot copy a drawing; an associative agnosic copies it slavishly and still cannot recognize it", "The lower lateral occipital cortex represents the upper visual field"],
 [S(8, 288, 291), S(7, 258, 260), B(6, 47, 52), B(7, 58, 60)], synonyms=["lateral occipital complex (inferior)", "areas 18/19 (inferior lateral)"], territories=["territory-pca-occipital", "territory-mca-occipital"], pathways=["pathway-visual"], syndromes=["syn-homonymous-hemianopia", "syn-pca-infarct"],
 afferents=[("Primary visual cortex and lingual gyrus", "short association fibers"), ("Pulvinar", "thalamocortical fibers"), ("Contralateral occipital cortex", "splenium")],
 efferents=[("Occipital and temporal fusiform cortex", "inferior longitudinal fasciculus"), ("Inferior temporal gyrus", "short association fibers"), ("Posterior parietal cortex", "vertical occipital fasciculus")],
 pitfalls=["Hallucinations in a patient with poor vision should prompt an eye examination and an occipital MRI before antipsychotics"], tags=["ventral stream", "shape", "upper quadrant"]))

E.append(cortex("cortex-intracalcarine", "Intracalcarine cortex", "occipital",
 "The intracalcarine cortex is the primary visual cortex buried in the walls of the calcarine sulcus on the medial occipital surface, the striate cortex of Brodmann area 17 named for the stria of Gennari visible to the naked eye. The upper wall receives the contralateral lower visual field and the lower wall the upper field, with the macula represented at the occipital pole and the far periphery at the anterior end near the parieto-occipital junction. It is supplied by the calcarine branch of the posterior cerebral artery, so a PCA occlusion produces a congruous contralateral homonymous hemianopia, often with macular sparing; bilateral destruction causes cortical blindness and, with unawareness, Anton syndrome.",
 "Cortex lining the calcarine sulcus from the occipital pole forward to its junction with the parieto-occipital sulcus, between the cuneus above and the lingual gyrus below, facing the falx and the contralateral calcarine cortex.",
 "Striate cortex receives the geniculocalcarine radiation in layer IV, where the stria of Gennari marks the dense myelinated input, and analyzes the retinal image into oriented edges, spatial frequencies, binocular disparity and color contrast within a precise retinotopic map in which the central few degrees occupy the posterior half. It sends its output to the surrounding extrastriate areas on the cuneus and lingual gyrus and to the dorsal and ventral streams, and it projects back to the lateral geniculate nucleus and to the superior colliculus. Destructive lesions cause a congruous field defect in the contralateral hemifield, and irritative lesions cause elementary hallucinations of flashes and colored shapes in the corresponding location.",
 PCA + MCA_I,
 [mview("sagittal", "cortex-intracalcarine-l", "calcarine sulcus on the medial occipital surface"), mview("axial", "cortex-intracalcarine-r", "striate cortex within the calcarine fissure")],
 "The deep horizontal calcarine sulcus on medial sagittal images, running from the occipital pole to the parieto-occipital sulcus; on high-resolution T1 images the stria of Gennari appears as a thin dark line within the gray matter.",
 [pathol("PCA infarct with homonymous hemianopia", "MRI", "Restricted diffusion of the calcarine cortex and adjacent cuneus and lingual gyrus; the occipital pole is often spared through MCA collaterals.", sequence="DWI"),
  pathol("Cortical blindness / Anton syndrome", "MRI", "Bilateral calcarine infarcts, typically from basilar or bilateral PCA occlusion, with blindness that the patient denies.", sequence="DWI"),
  pathol("Occipital epilepsy", "EEG", "Elementary visual hallucinations in the contralateral field followed by ictal blindness or eye deviation; occipital spikes accentuated by eye closure.", sequence="n/a")],
 [("Contralateral congruous homonymous hemianopia", "contralateral", "Destruction of the whole calcarine cortex of one side"), ("Contralateral quadrantanopia", "contralateral", "Lesion confined to the upper (lower field) or lower (upper field) calcarine bank"), ("Cortical blindness with preserved pupils", "bilateral", "Bilateral striate destruction; the pupillary pathway leaves the visual pathway before the cortex")],
 ["Confrontation fields in all quadrants and formal perimetry", "Pupillary light reflexes, which are normal in cortical visual loss", "Ask about awareness of the deficit and check for confabulation about what is seen"],
 ["A hemianopia with normal pupils and macular sparing is calcarine cortex, not optic tract", "Cortical blindness with denial is Anton syndrome; the patient walks into furniture and blames the light", "The macula sits at the occipital pole where MCA and PCA branches overlap, which is why it survives a PCA occlusion"],
 [S(8, 288, 289), S(7, 259, 260), S(11, 333, 336), S(17, 468, 470), B(6, 47, 52)], synonyms=["primary visual cortex", "striate cortex", "area 17", "V1"], territories=["territory-pca-occipital"], pathways=["pathway-visual", "pathway-pupillary-light-reflex"], syndromes=["syn-homonymous-hemianopia", "syn-anton", "syn-pca-infarct", "syn-top-of-basilar"],
 afferents=[("Lateral geniculate nucleus", "optic radiation (geniculocalcarine tract)"), ("Pulvinar", "thalamocortical fibers"), ("Contralateral calcarine cortex (vertical meridian)", "splenium")],
 efferents=[("Cuneus, lingual gyrus and lateral occipital cortex (V2-V5)", "short association fibers"), ("Lateral geniculate nucleus and pulvinar", "corticothalamic fibers"), ("Superior colliculus and pretectum", "corticotectal fibers")],
 pitfalls=["Cortical visual loss with a normal fundus and normal pupils is often called functional; perimetry and MRI settle it"], tags=["V1", "striate", "calcarine"]))

E.append(cortex("cortex-supracalcarine", "Supracalcarine cortex", "occipital",
 "The supracalcarine cortex is the strip of medial occipital cortex immediately above the calcarine sulcus, on the lower edge of the cuneus, where the primary visual cortex emerges from the sulcus and merges with the surrounding secondary visual cortex (V2). It represents the contralateral lower visual field close to the horizontal meridian, and its retinotopic map continues that of the calcarine cortex. It is supplied by the calcarine branch of the posterior cerebral artery and shares the vulnerability of the cuneus to PCA infarction, posterior reversible encephalopathy and occipital seizures; its lesions produce a contralateral inferior quadrantic defect that respects the horizontal meridian.",
 "Medial occipital cortex along the upper lip of the calcarine sulcus, between the intracalcarine cortex below and the body of the cuneus above, from the occipital pole to the junction with the parieto-occipital sulcus.",
 "The supracalcarine strip contains the upper-bank continuation of V1 and the neighboring V2, which sharpens edges and combines the orientation, color and disparity signals of the striate cortex into border ownership and texture, feeding both dorsal and ventral streams; the horizontal meridian of the visual field maps to the border between V1 and V2 here, which is why lesions produce field defects with a sharp horizontal edge. The cortex receives callosal fibers from the opposite side that stitch the two hemifields together along the vertical meridian and projects to the parietal and lateral occipital cortex for localization of objects in the lower field.",
 PCA,
 [mview("sagittal", "cortex-supracalcarine-l", "supracalcarine cortex along the upper lip of the calcarine sulcus"), mview("coronal", "cortex-supracalcarine-r", "medial occipital cortex just above the calcarine fissure")],
 "The medial cortex immediately above the calcarine sulcus on sagittal images, continuous with the cuneus; it is thin and follows the curve of the sulcus to the pole.",
 [pathol("PCA infarct with inferior quadrantanopia", "MRI", "Restricted diffusion along the upper calcarine lip and cuneus with a contralateral lower quadrant defect that stops at the horizontal meridian.", sequence="DWI"),
  pathol("Occipital arteriovenous malformation", "MRI", "Flow voids on the medial occipital surface with hemosiderin staining, presenting with visual seizures or hemorrhage.", sequence="T2"),
  pathol("Posterior reversible encephalopathy syndrome", "MRI", "Vasogenic edema of the medial occipital cortex with transient visual loss, headache and seizures.", sequence="FLAIR")],
 [("Contralateral inferior quadrantanopia respecting the horizontal meridian", "contralateral", "Loss of the upper calcarine bank and V2 representing the lower field"), ("Elementary visual hallucinations in the lower contralateral field", "contralateral", "Ictal activation of the supracalcarine visual cortex"), ("Impaired localization of objects in the lower field", "contralateral", "Loss of the projection from this cortex to the dorsal stream")],
 ["Quadrantic confrontation fields with attention to a horizontal edge of the defect", "Perimetry to define the meridian and congruity", "Seizure history for brief lower-field flashes"],
 ["A field defect with a straight horizontal edge is calcarine: the horizontal meridian is the V1-V2 border on the lips of the sulcus", "Occipital AVMs present with seizures and headache and can mimic migraine with aura for years", "The supracalcarine and cuneal cortex are one functional unit for the lower field"],
 [S(8, 288, 289), S(7, 259, 260), S(11, 333, 336), B(6, 47, 52)], synonyms=["upper calcarine lip", "V1/V2 (superior)"], territories=["territory-pca-occipital"], pathways=["pathway-visual"], syndromes=["syn-homonymous-hemianopia", "syn-pca-infarct"],
 afferents=[("Lateral geniculate nucleus (lower field)", "optic radiation, upper bank"), ("Intracalcarine cortex (V1)", "short association fibers"), ("Contralateral supracalcarine cortex", "splenium")],
 efferents=[("Cuneus and superior lateral occipital cortex (dorsal stream)", "short association fibers"), ("Pulvinar", "corticothalamic fibers"), ("Superior colliculus", "corticotectal fibers")],
 pitfalls=["Small calcarine lesions produce field defects that patients do not notice; a routine field examination after any PCA event is needed"], tags=["V1", "V2", "lower quadrant"]))

E.append(cortex("occipital-pole", "Occipital pole", "occipital",
 "The occipital pole is the posterior tip of the hemisphere where the calcarine sulcus reaches the surface and the primary visual cortex spreads onto the lateral convexity, representing the central visual field (the macula) with a huge cortical magnification. It receives a dual blood supply from the calcarine branch of the posterior cerebral artery and from the terminal branches of the middle cerebral artery, which is why the macula is spared in many PCA infarcts and why the pole is selectively damaged in watershed injury and in hypotension. Bilateral polar lesions cause central scotomas and loss of reading, and the pole is the site of the visual auras of occipital epilepsy and of the release hallucinations of visual loss.",
 "Posterior extremity of the hemisphere, behind the parieto-occipital sulcus and the preoccipital notch, where the medial, lateral and inferior surfaces of the occipital lobe converge; the calcarine sulcus ends here and the macular representation extends onto the lateral surface.",
 "The posterior calcarine cortex at the pole receives the foveal projection, with the central few degrees occupying as much cortex as the whole peripheral field, and analyzes the fine detail, color and stereopsis needed for reading, face recognition and skilled hand work; it feeds the fusiform and lateral occipital areas that identify letters and objects. The vertical meridian is represented at the border with the opposite hemisphere through the splenium, and the pole contributes to the maintenance of fixation and to the smallest voluntary saccades. Its loss on one side produces a congruous contralateral paracentral scotoma or a hemianopia without macular sparing.",
 PCA + MCA_I,
 [mview("axial", "occipital-pole-l", "occipital pole with the macular representation"), mview("sagittal", "occipital-pole-r", "posterior tip of the hemisphere at the end of the calcarine sulcus")],
 "Rounded posterior tip of the hemisphere on axial and sagittal images, where the calcarine sulcus reaches the surface; the poles are often asymmetric with one petalia projecting further back, a normal variant.",
 [pathol("Occipital pole watershed infarct", "MRI", "Bilateral restricted diffusion of the occipital tips after hypotension or cardiac arrest with central scotomas and impaired reading despite preserved peripheral fields.", sequence="DWI"),
  pathol("PCA infarct with macular splitting", "MRI", "Calcarine infarct extending to the pole when the MCA collateral is poor, producing a complete hemianopia without macular sparing.", sequence="DWI"),
  pathol("Occipital epilepsy", "EEG", "Central colored or flashing auras, ictal blindness or amaurosis, occipital spikes increased by eye closure.", sequence="n/a")],
 [("Contralateral paracentral scotoma or hemianopia without macular sparing", "contralateral", "Loss of the foveal representation at the occipital pole"), ("Bilateral central scotomas and impaired reading", "bilateral", "Bilateral polar damage in border-zone injury"), ("Central elementary visual hallucinations", "n/a", "Ictal activation of the macular cortex")],
 ["Central fields with a red target and the Amsler grid", "Reading acuity in addition to distance acuity", "Perimetry for paracentral and macular defects"],
 ["The macula has two arteries; the occipital pole is spared by a PCA stroke and hit by a hypotensive one", "Bilateral occipital pole infarcts give a patient who walks confidently but cannot read", "Occipital petalia (one pole projecting further back) is a normal asymmetry seen on every MRI"],
 [S(8, 288, 289), S(7, 256, 260), S(17, 468, 470), B(6, 47, 52), B(7, 58, 60)], synonyms=["macular cortex", "posterior calcarine cortex"], territories=["territory-pca-occipital", "territory-mca-occipital"], pathways=["pathway-visual"], syndromes=["syn-watershed-infarct", "syn-homonymous-hemianopia", "syn-pca-infarct"],
 afferents=[("Lateral geniculate nucleus (foveal fibers)", "optic radiation"), ("Contralateral occipital pole (vertical meridian)", "splenium"), ("Pulvinar", "thalamocortical fibers")],
 efferents=[("Fusiform and lateral occipital cortex", "short association fibers"), ("Superior colliculus (fixation)", "corticotectal fibers"), ("Lateral geniculate nucleus", "corticogeniculate feedback")],
 pitfalls=["Macular sparing is not a sign of a benign lesion; it only reflects the dual blood supply of the pole"], tags=["macula", "V1", "watershed"]))

E.append(cortex("gyrus-lingual", "Lingual gyrus", "occipital",
 "The lingual gyrus is the tongue-shaped gyrus on the inferomedial occipital surface below the calcarine sulcus, extending forward to the isthmus of the cingulate gyrus and bounded laterally by the collateral sulcus and the fusiform gyrus. It is the lower bank of the primary visual cortex and its surrounding V2, V3 and ventral V4, and it represents the contralateral upper visual field; it also processes color and, together with the parahippocampal cortex in front of it, the recognition of places and landmarks. It is supplied by the posterior cerebral artery, and its lesions produce contralateral superior quadrantanopia, hemiachromatopsia and topographical disorientation.",
 "Inferomedial occipital gyrus between the calcarine sulcus above and the collateral sulcus below and laterally, from the occipital pole forward to the isthmus behind the splenium, continuous anteriorly with the parahippocampal gyrus.",
 "The lower calcarine bank on the lingual gyrus receives the geniculocalcarine fibers carrying the contralateral upper field, and the surrounding ventral extrastriate cortex analyzes color, texture and the layout of scenes; the anterior lingual and neighboring parahippocampal cortex form the place area that recognizes landmarks and the spatial structure of environments. The gyrus feeds the fusiform recognition regions laterally and the retrosplenial and hippocampal navigation system anteriorly. Damage produces an upper quadrantic defect, loss of color in the contralateral field and inability to recognize familiar places, and irritation produces colored hallucinations in the upper field.",
 PCA,
 [mview("sagittal", "gyrus-lingual-l", "lingual gyrus below the calcarine sulcus"), mview("coronal", "gyrus-lingual-r", "inferomedial occipital cortex between the calcarine and collateral sulci")],
 "Medial occipital gyrus below the calcarine sulcus on sagittal images, tapering forward toward the splenium; on coronal images it lies medial to the collateral sulcus and the fusiform gyrus.",
 [pathol("PCA infarct (lower calcarine bank)", "MRI", "Restricted diffusion of the lingual gyrus with a contralateral superior quadrantanopia and, with extension laterally, hemiachromatopsia.", sequence="DWI"),
  pathol("Landmark agnosia", "MRI", "Right lingual and parahippocampal infarct or tumor with inability to recognize familiar buildings and places despite preserved object recognition.", sequence="FLAIR"),
  pathol("Occipital seizures", "EEG", "Colored visual hallucinations in the upper contralateral field with an occipital focus.", sequence="n/a")],
 [("Contralateral superior quadrantanopia", "contralateral", "Loss of the lower calcarine bank representing the upper field"), ("Contralateral hemiachromatopsia", "contralateral", "Damage to ventral V4 on the lingual and fusiform surface"), ("Landmark agnosia and topographical disorientation (right)", "n/a", "Loss of the lingual-parahippocampal place recognition cortex")],
 ["Upper quadrant fields by confrontation", "Color naming and matching in each hemifield", "Recognition of familiar buildings and route description"],
 ["Below the calcarine sulcus means the upper field: lingual lesions cut the upper quadrant", "A patient who gets lost in familiar streets despite recognizing objects has a right lingual-parahippocampal lesion", "Hemiachromatopsia accompanies upper quadrant defects because V4 lies on the ventral surface"],
 [S(8, 288, 289), S(7, 259, 260), S(11, 333, 336), B(6, 47, 52), B(7, 58, 60)], synonyms=["lower calcarine bank", "medial occipitotemporal gyrus"], territories=["territory-pca-occipital"], pathways=["pathway-visual"], syndromes=["syn-homonymous-hemianopia", "syn-pca-infarct"],
 afferents=[("Lateral geniculate nucleus (upper field fibers)", "optic radiation, lower bank"), ("Pulvinar", "thalamocortical fibers"), ("Contralateral lingual gyrus", "splenium")],
 efferents=[("Fusiform gyrus (ventral stream)", "short association fibers"), ("Parahippocampal and retrosplenial cortex", "short association fibers"), ("Superior colliculus", "corticotectal fibers")],
 pitfalls=["Upper quadrant defects are attributed to the temporal loop of the radiation, but a lingual cortical lesion gives the same field defect with cortical signs"], tags=["V1", "V4", "place area", "upper quadrant"]))

E.append(cortex("gyrus-occipital-fusiform", "Occipital fusiform gyrus", "occipital",
 "The occipital fusiform gyrus is the posterior end of the fusiform gyrus on the inferior surface of the occipital lobe, between the collateral sulcus and the lingual gyrus medially and the inferior lateral occipital cortex laterally, behind the temporo-occipital fusiform cortex. It is ventral extrastriate cortex (parts of V2, V3, V4 and the posterior lateral occipital complex) that represents the contralateral upper field and begins the analysis of color, texture and shape that the fusiform recognition areas complete. It is supplied by the posterior cerebral artery, and its lesions add hemiachromatopsia and apperceptive agnosia to a superior quadrantanopia; bilateral lesions give achromatopsia and visual form agnosia.",
 "Inferior occipital surface behind the temporo-occipital junction, between the collateral sulcus medially and the lateral occipital sulcus laterally, above the tentorium and below the calcarine cortex.",
 "The occipital fusiform cortex contains retinotopic ventral visual areas that compute color constancy, surface texture and the curvature of contours, integrating them into the shape descriptions used by the face, word and object areas of the fusiform gyrus in front; the contralateral upper visual field is represented, with the vertical meridian at its lateral border. It projects along the inferior longitudinal fasciculus and receives feedback from the parietal and frontal attention systems. Lesions produce loss of color and shape perception in the contralateral upper field and, with extension medially, a quadrantanopia; seizures here produce colored auras in the upper field.",
 PCA,
 [mview("coronal", "gyrus-occipital-fusiform-l", "occipital fusiform gyrus on the inferior occipital surface"), mview("axial", "gyrus-occipital-fusiform-r", "ventral occipital cortex lateral to the lingual gyrus")],
 "The gyrus on the inferior occipital surface lateral to the collateral sulcus on coronal images behind the atrium, above the tentorial surface and below the level of the calcarine sulcus.",
 [pathol("PCA infarct with hemiachromatopsia", "MRI", "Restricted diffusion of the inferior occipital cortex with loss of color vision in the contralateral hemifield and an upper quadrant defect.", sequence="DWI"),
  pathol("Cerebral achromatopsia", "MRI", "Bilateral ventral occipital lesions with complete loss of color vision, the world seen in gray; usually with prosopagnosia and upper field defects.", sequence="FLAIR"),
  pathol("Tentorial meningioma", "MRI", "Dural enhancing mass on the tentorium indenting the inferior occipital surface with visual field loss and seizures.", sequence="T1+Gd")],
 [("Contralateral hemiachromatopsia", "contralateral", "Loss of the ventral V4 color-constancy cortex"), ("Contralateral superior quadrantanopia", "contralateral", "Involvement of the lower calcarine bank or the ventral retinotopic areas"), ("Apperceptive agnosia when bilateral", "bilateral", "Loss of ventral form processing on both sides")],
 ["Color plates presented separately to each hemifield", "Upper quadrant fields", "Shape copying and matching"],
 ["Color is processed on the underside of the occipital lobe; a tentorial tumor can present with washed-out color on one side", "Achromatopsia is cortical color blindness with normal cones and normal acuity", "Upper field defects plus color loss point below the calcarine sulcus"],
 [S(8, 288, 291), S(7, 259, 260), B(6, 47, 52), B(7, 58, 60)], synonyms=["posterior fusiform gyrus", "ventral V4"], territories=["territory-pca-occipital"], pathways=["pathway-visual"], syndromes=["syn-pca-infarct", "syn-homonymous-hemianopia"],
 afferents=[("Primary and secondary visual cortex", "short association fibers"), ("Pulvinar", "thalamocortical fibers"), ("Contralateral ventral occipital cortex", "splenium")],
 efferents=[("Temporo-occipital and temporal fusiform cortex", "inferior longitudinal fasciculus"), ("Inferior lateral occipital cortex", "short association fibers"), ("Lateral geniculate nucleus", "corticogeniculate feedback")],
 pitfalls=["Hemiachromatopsia is unrecognized unless colors are tested by hemifield; standard testing at fixation misses it"], tags=["V4", "color", "ventral stream"]))

write(E)
